package com.hrm.gui;
import com.hrm.service.MaintenanceService;import javax.swing.*;import java.awt.*;
public class MaintenancePanel extends JPanel{public MaintenancePanel(){setLayout(new BorderLayout(10,10));add(Ui.top("Bao tri & kiem tra he thong - ADMIN"),BorderLayout.NORTH);JTextArea a=new JTextArea();a.setEditable(false);JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton test=Ui.btn("Kiem tra ket noi"),stats=Ui.btn("Kiem tra du lieu"),opt=Ui.btn("Toi uu bang");b.add(test);b.add(stats);b.add(opt);add(b,BorderLayout.SOUTH);add(new JScrollPane(a),BorderLayout.CENTER);MaintenanceService s=new MaintenanceService();test.addActionListener(e->a.append(s.testConnection()+System.lineSeparator()));stats.addActionListener(e->{try{a.append(s.systemStats()+System.lineSeparator());}catch(Exception ex){Ui.error(this,ex);}});opt.addActionListener(e->{try{a.append(s.optimize()+System.lineSeparator());}catch(Exception ex){Ui.error(this,ex);}});}}
